import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Flow - Visual Strategy Builder","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/flow-visual-strategy-builder.md","filePath":"new-features/flow-visual-strategy-builder.md"}'),s={name:"new-features/flow-visual-strategy-builder.md"};function r(n,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="flow-visual-strategy-builder" tabindex="-1">Flow - Visual Strategy Builder <a class="header-anchor" href="#flow-visual-strategy-builder" aria-label="Permalink to &quot;Flow - Visual Strategy Builder&quot;">​</a></h1><p>Flow is Tradeboard&#39;s visual workflow editor and synchronous execution engine. A workflow is a directed graph with exactly one trigger and a reachable chain of data, condition, trading, streaming, and notification nodes.</p><h2 id="current-capabilities" tabindex="-1">Current Capabilities <a class="header-anchor" href="#current-capabilities" aria-label="Permalink to &quot;Current Capabilities&quot;">​</a></h2><ul><li>61 node types kept in parity across the editor, backend validator, executor, and tests.</li><li>Four triggers: Schedule, Price Alert, Webhook, and Order Update.</li><li>Regular, smart, options, basket, split, modify, cancel, and close-position actions.</li><li>Quote, depth, history, indicator, account, options, and calendar data nodes.</li><li>Branch conditions and AND/OR/NOT gates.</li><li>LTP/Quote/Depth subscriptions, logging, variables, math, HTTP requests, delays, wait-until, Telegram, and WhatsApp actions.</li><li>Strategy-level realized/unrealized P&amp;L.</li><li>JSON import, export, and validated in-place replacement.</li><li>Execution history and per-node logs.</li></ul><p>Flow does not provide loops, foreach/switch nodes, cross-run variables, automatic retry/error-handler nodes, built-in backtesting, or version-control history.</p><h2 id="build-a-workflow" tabindex="-1">Build a Workflow <a class="header-anchor" href="#build-a-workflow" aria-label="Permalink to &quot;Build a Workflow&quot;">​</a></h2><ol><li>Open <code>/flow</code> and create a workflow.</li><li>Drag one trigger onto the canvas.</li><li>Add downstream nodes and connect them in execution order.</li><li>Configure each node. Give a producer an <code>outputVariable</code> when a later node needs its result.</li><li>Branch from conditions using the <code>true</code>/<code>false</code> or <code>yes</code>/<code>no</code> handles.</li><li>Save while editing. Incomplete graphs may be saved, but corrupt node types, duplicate IDs, and dangling edges are rejected.</li><li>Use <strong>Run Now</strong> to validate and test a complete graph.</li><li>Activate the workflow when its trigger should remain registered.</li></ol><h2 id="trigger-types" tabindex="-1">Trigger Types <a class="header-anchor" href="#trigger-types" aria-label="Permalink to &quot;Trigger Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>Behavior</th><th>Important configuration</th></tr></thead><tbody><tr><td>Schedule (<code>start</code>)</td><td>Once, daily, weekly, or interval execution</td><td>IST time/day values and an optional market-hours gate driven by the exchange calendar, with optional exchange and <code>HH:MM</code> overrides</td></tr><tr><td>Price Alert (<code>priceAlert</code>)</td><td>Watches LTP for a level, cross, channel, or percentage move</td><td>Symbol/exchange, thresholds, once/every-time, expiration</td></tr><tr><td>Webhook (<code>webhookTrigger</code>)</td><td>Executes from a tokenized public POST</td><td>Optional symbol filter and payload or URL-secret authentication</td></tr><tr><td>Order Update (<code>orderUpdateTrigger</code>)</td><td>Executes on normalized live/sandbox order state</td><td>Order ID or symbol filter, optional exchange/status, once/every-time</td></tr></tbody></table><p>Every complete workflow must contain exactly one trigger. Multiple triggers, cycles, unreachable executable nodes, invalid edges, missing required fields, and oversized graphs are rejected before a broker call.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><p>Use <code>&amp;#123;&amp;#123;path&amp;#125;&amp;#125;</code> inside string fields:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{quote.data.ltp}}</span></span>
<span class="line"><span>{{chain.data.results[0].ce.ltp}}</span></span>
<span class="line"><span>{{webhook.symbol}}</span></span>
<span class="line"><span>{{timestamp}}</span></span>
<span class="line"><span>{{session_date}}</span></span></code></pre></div><p>Dotted dictionary keys and non-negative list indexes are supported. Most missing paths remain literal in the rendered string so the execution log exposes the mistake. A Variable Condition is stricter: an unresolved operand takes neither branch.</p><h2 id="example-signal-to-order" tabindex="-1">Example: Signal to Order <a class="header-anchor" href="#example-signal-to-order" aria-label="Permalink to &quot;Example: Signal to Order&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Webhook Trigger -&gt; Place Order -&gt; Telegram Alert</span></span></code></pre></div><p>Configure order fields with payload values such as <code>&amp;#123;&amp;#123;webhook.symbol&amp;#125;&amp;#125;</code>, <code>&amp;#123;&amp;#123;webhook.action&amp;#125;&amp;#125;</code>, and <code>&amp;#123;&amp;#123;webhook.quantity&amp;#125;&amp;#125;</code>. Give the order an output variable such as <code>order</code>, then notify with <code>&amp;#123;&amp;#123;order.orderid&amp;#125;&amp;#125;</code>.</p><p>Webhook URLs are:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /flow/webhook/&lt;token&gt;</span></span>
<span class="line"><span>POST /flow/webhook/&lt;token&gt;/&lt;symbol&gt;</span></span></code></pre></div><p>Tokens and secrets are generated by the server. Use HTTPS for an internet-facing webhook.</p><h2 id="import-export-and-replace" tabindex="-1">Import, Export, and Replace <a class="header-anchor" href="#import-export-and-replace" aria-label="Permalink to &quot;Import, Export, and Replace&quot;">​</a></h2><p>Imported JSON uses this top-level shape:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Example&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;nodes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;edges&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []}</span></span></code></pre></div><p>Import creates a new workflow. <strong>Replace from JSON</strong> changes the graph of an existing workflow while preserving its ID, webhook token/secret, API key, and active flag. If active trigger configuration changes, deactivate and reactivate the workflow so the trigger is registered again.</p><p>See <a href="./../flow-editor/README.html">Flow Editor</a> for the execution model, complete node reference, import behavior, tested tutorials, and current limitations.</p><h2 id="execution-and-safety" tabindex="-1">Execution and Safety <a class="header-anchor" href="#execution-and-safety" aria-label="Permalink to &quot;Execution and Safety&quot;">​</a></h2><ul><li>One per-workflow lock prevents overlapping executions of the same workflow.</li><li>A graph is limited to 500 nodes, 1000 edges, depth 100, and 500 total node visits.</li><li>Schedule jobs use <code>coalesce=true</code>, <code>max_instances=1</code>, and a 60-second misfire grace.</li><li>Active price and order-update watches are removed on deactivation/deletion and restored after restart when persisted configuration permits it.</li><li>Order nodes use the same service layer and Analyzer/semi-auto routing rules as the REST API.</li><li>Delay nodes and external broker/HTTP calls keep execution synchronous; avoid long waits across many active workflows. A <code>delay</code> node is capped at 300 seconds, while <code>waitUntil</code> is uncapped and holds the workflow lock for its full duration.</li></ul>`,27)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
